import{c as r,Q as o,j as t,m as a}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"12-Rule Canon — Claude Slim（core.md 格式）","description":"","frontmatter":{},"headers":[],"relativePath":"research/reports/archive/2026-06-04-12-rule-canon-CLAUDE-slim.md","filePath":"research/reports/archive/2026-06-04-12-rule-canon-CLAUDE-slim.md","lastUpdated":1780842316000}'),n={name:"research/reports/archive/2026-06-04-12-rule-canon-CLAUDE-slim.md"};function s(i,e,l,c,d,g){return o(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="_12-rule-canon-—-claude-slim-core-md-格式" tabindex="-1">12-Rule Canon — Claude Slim（core.md 格式） <a class="header-anchor" href="#_12-rule-canon-—-claude-slim-core-md-格式" aria-label="Permalink to &quot;12-Rule Canon — Claude Slim（core.md 格式）&quot;">​</a></h1><blockquote><p>可部署版：格式對齊 <code>.claude/rules/core.md</code>，Claude Code 可直接讀取（auto-load 或 on-demand）。 每條 = 強制條文 + 機械驗證指令。完整檢查表/失敗案例見 <code>refs/karpathy-mnilax-best-solution.md</code>。 <strong>下限</strong>：§R1–R12 行為條文 + 驗證指令一字不可砍；可砍的只有 rationale/史料。</p></blockquote><h2 id="語言" tabindex="-1">語言 <a class="header-anchor" href="#語言" aria-label="Permalink to &quot;語言&quot;">​</a></h2><p>中文 → 台灣繁體（技術術語保留英文：kubectl/Terraform/Pod/SLO）；English → English。Session 後段、compact 後、工具輸出以英文為主時仍維持繁中。</p><h2 id="生產環境安全紅線" tabindex="-1">生產環境安全紅線 <a class="header-anchor" href="#生產環境安全紅線" aria-label="Permalink to &quot;生產環境安全紅線&quot;">​</a></h2><p>Production（GCP/TF/K8s 含 <code>prod</code>）apply/deploy/delete → 先 plan/diff，再二次確認。</p><hr><h2 id="§r1-—-think-before-coding" tabindex="-1">§R1 — Think Before Coding <a class="header-anchor" href="#§r1-—-think-before-coding" aria-label="Permalink to &quot;§R1 — Think Before Coding&quot;">​</a></h2><p><strong>防</strong>：沉默假設、隱藏困惑。 實作前先講 ≤2 句：(1) 對需求的詮釋（非複述）；(2) 關鍵假設。多解釋 → 列選項讓用戶確認，不自選。瑣碎等價選擇（命名/格式/預設）→ 自決並一句註明。scope 變更/破壞性 → 必問。 <strong>不可逆例外（即使「直接做」）</strong>：<code>DELETE</code>/<code>DROP</code>/<code>TRUNCATE</code>/prod deploy/key rotate/<code>rm -rf</code>/<code>git push --force</code>/<code>terraform destroy</code>/<code>kubectl delete</code> → 顯示摘要 + 等待確認。 <strong>驗</strong>：首次 edit 前 transcript 有詮釋+假設行；任何破壞性關鍵字有確認摘要。</p><h2 id="§r2-—-simplicity-first" tabindex="-1">§R2 — Simplicity First <a class="header-anchor" href="#§r2-—-simplicity-first" aria-label="Permalink to &quot;§R2 — Simplicity First&quot;">​</a></h2><p><strong>防</strong>：過度工程（speculative feature / 單次使用抽 helper / 不可能輸入的 error 分支）。 寫最小能解決問題的代碼。Rule of 3：≥3 呼叫點才抽。自檢：「資深工程師會說太複雜嗎？」是 → 砍最簡。 <strong>安全例外（永遠共用函式，不受呼叫點計數限制）</strong>：加密原語/金鑰操作/輸入驗證/身份驗證；禁各算法 inline nonce/IV。 <strong>驗</strong>：diff 無 ❤️ 呼叫點抽象、無未要求 config/flag、無不可能輸入的分支。</p><h2 id="§r3-—-surgical-changes" tabindex="-1">§R3 — Surgical Changes <a class="header-anchor" href="#§r3-—-surgical-changes" aria-label="Permalink to &quot;§R3 — Surgical Changes&quot;">​</a></h2><p><strong>防</strong>：周邊污染（順手 refactor/rename/reformat）、wide-blast-radius cascade。 只動任務要求的最小範圍；match 既有風格。只清自己造的 orphan，pre-existing dead code 記錄不刪。任務外 bug → 記錄回報不自動修（commit 原子性）。 <strong>P0 安全例外（發現即修，獨立分支）</strong>：硬編碼憑證/SQLi/Path Traversal/Auth Bypass。 <strong>驗</strong>：每改動行可追溯至需求。軟界線：bug fix ≤50 行、功能 ≤300、單檔 ≤500。</p><h2 id="§r4-—-goal-driven-execution" tabindex="-1">§R4 — Goal-Driven Execution <a class="header-anchor" href="#§r4-—-goal-driven-execution" aria-label="Permalink to &quot;§R4 — Goal-Driven Execution&quot;">​</a></h2><p><strong>防</strong>：弱成功條件下走步驟、卡在「下一步」。 開工前把任務轉成可觀測成功條件，迭代到達標。「加驗證」→「為無效輸入寫測試再使其通過」；「修 bug」→「寫重現測試再使其通過」。 <strong>驗</strong>：成功條件可機械驗證（命令 exit 0 / test pass / 特定輸出）——非「看起來正確」。驗證指令實際跑過且<strong>展示前 5 行/後 5 行輸出</strong>，失敗完整貼錯誤。</p><h2 id="§r5-—-judgment-vs-decisions" tabindex="-1">§R5 — Judgment vs Decisions <a class="header-anchor" href="#§r5-—-judgment-vs-decisions" aria-label="Permalink to &quot;§R5 — Judgment vs Decisions&quot;">​</a></h2><p><strong>防</strong>：用 LLM 做確定性工作（非確定答案回答確定問題）。 <strong>LLM（判斷）</strong>：分類/摘要/提取/創意生成。<strong>確定性代碼（決定）</strong>：路由/重試/HTTP status/數學/格式轉換。 <strong>驗</strong>：無 control-flow 決策（route/retry/branch on known signal）委派給 model call。</p><h2 id="§r6-—-token-budget" tabindex="-1">§R6 — Token Budget <a class="header-anchor" href="#§r6-—-token-budget" aria-label="Permalink to &quot;§R6 — Token Budget&quot;">​</a></h2><p><strong>防</strong>：loop 失控耗盡 context、context collapse 下品質靜默衰退。 設明確 per-task / per-session token 預算（依模型+價格）。逼近 → summarize 並 start fresh，不硬推。compact 用 incremental/delta 摘要保留 goal+key results（full-rewrite <em>導致</em> collapse）。 <strong>驗</strong>：預算數字存在且被檢查。breach 時 agent compact/restart 並<strong>明說</strong>，不靜默續跑。</p><blockquote><p>數字依模型而定，自行設；原則（明確預算+浮現 breach）通用。詳見 <code>context-management.md</code>。</p></blockquote><h2 id="§r7-—-surface-conflicts" tabindex="-1">§R7 — Surface Conflicts <a class="header-anchor" href="#§r7-—-surface-conflicts" aria-label="Permalink to &quot;§R7 — Surface Conflicts&quot;">​</a></h2><p><strong>防</strong>：混用兩矛盾模式成「平均」代碼，兩邊都不滿足。 兩模式矛盾 → 擇一，優先序 ADR/CONTRIBUTING &gt; 最近 commit &gt; 覆蓋率。說明原因，flag 另一個。不混用。 <strong>驗</strong>：選定模式一致（非 hybrid）；有 <code>TODO(conflict): chose A over B; reason …; remove B before &lt;milestone&gt;</code>。</p><h2 id="§r8-—-read-before-write" tabindex="-1">§R8 — Read Before Write <a class="header-anchor" href="#§r8-—-read-before-write" aria-label="Permalink to &quot;§R8 — Read Before Write&quot;">​</a></h2><p><strong>防</strong>：未懂介面契約/上游影響就改。「Looks orthogonal」最危險。 改前讀：exports（介面）+ 直接 caller（上游）+ 共用 utility（橫向依賴）。不懂現有結構為何如此 → 先問再加。 <strong>驗</strong>：transcript 顯示相關 exports/callers 在 edit <strong>之前</strong>被讀（read 先於 write）。</p><h2 id="§r9-—-tests-verify-intent" tabindex="-1">§R9 — Tests Verify Intent <a class="header-anchor" href="#§r9-—-tests-verify-intent" aria-label="Permalink to &quot;§R9 — Tests Verify Intent&quot;">​</a></h2><p><strong>防</strong>：能通過任何實作的測試（假測試）。 每個測試編碼「為何此行為重要」。mock 外部邊界非業務核心。寫不出「業務邏輯改變時會失敗」的測試 = 函式有問題。 <strong>驗</strong>：翻轉一行業務邏輯 → 至少一個測試失敗。</p><h2 id="§r10-—-checkpoint" tabindex="-1">§R10 — Checkpoint <a class="header-anchor" href="#§r10-—-checkpoint" aria-label="Permalink to &quot;§R10 — Checkpoint&quot;">​</a></h2><p><strong>防</strong>：在無法描述的狀態上續跑、重複已做工作。 多步任務每步輸出一句：做了 X / 驗了 Y / 剩 Z。失去追蹤 → 停下重述，不在損壞狀態續跑。 <strong>驗</strong>：每重要步驟有 checkpoint 行且反映當前狀態。</p><h2 id="§r11-—-convention-first" tabindex="-1">§R11 — Convention First <a class="header-anchor" href="#§r11-—-convention-first" aria-label="Permalink to &quot;§R11 — Convention First&quot;">​</a></h2><p><strong>防</strong>：憑喜好 silent fork 慣例（snake_case→camelCase / class→hooks）。 codebase 內 conformance &gt; 偏好；不確定跟最近 3 commit。慣例有害（如 SQL 字串拼接）→ 明說 + flag，不 silent fork。 <strong>驗</strong>：新代碼 match 周邊 style/naming/structure；有害慣例被 flag 為議題非靜默跟隨。</p><h2 id="§r12-—-fail-loud" tabindex="-1">§R12 — Fail Loud <a class="header-anchor" href="#§r12-—-fail-loud" aria-label="Permalink to &quot;§R12 — Fail Loud&quot;">​</a></h2><p><strong>防</strong>：靜默失敗偽裝成功（「Migration 完成」但 30 筆被跳過）。 不確定是否成功 → 明說。跳過步驟/部分失敗必須陳述——語氣可調，資訊不省。報跳過/失敗計數 + log 指標。 <strong>驗</strong>：宣告完成前驗證指令跑過且<strong>展示輸出</strong>（非口頭「測試通過」）。任何 skip/partial-failure 具名數字。截斷的讀取/搜尋 flag，不假設為空。</p><hr><h2 id="compounding-meta-rule" tabindex="-1">Compounding（meta-rule） <a class="header-anchor" href="#compounding-meta-rule" aria-label="Permalink to &quot;Compounding（meta-rule）&quot;">​</a></h2><p>犯錯後問「會重演嗎？」→ 會 → 加 guard（可機械化用 hook/lint，否則寫規則）。只記<strong>已驗證</strong>約束，不記 speculative。同一失敗不得下次重演。active rules &gt; ~14 → 先 merge/cut 再加。</p>',35)])])}const p=r(n,[["render",s]]);export{u as __pageData,p as default};
